    try _v.visit(field: VT.ADDRESS, fieldName: "ADDRESS", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TOKEN_COUNT, fieldName: "TOKEN_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.COMPLETE, fieldName: "COMPLETE", required: false, type: Bool.self)
    try _v.visit(field: VT.VALUE, fieldName: "VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.BLOCK_HEIGHT, fieldName: "BLOCK_HEIGHT", required: false, type: UInt64.self)
    try _v.visit(field: VT.COMMITMENT, fieldName: "COMMITMENT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ERROR, fieldName: "ERROR", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}

///  Wallet Holdings Attestation - holdings of wallets across chains and their
///  value at one time.
public struct WHA: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$WHA" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: WHA.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let ATTESTATION_ID: VOffset = 4
    static let SUBJECT_ID: VOffset = 6
    static let PURPOSE: VOffset = 8
    static let ACCOUNTS: VOffset = 10
    static let HOLDINGS: VOffset = 12
    static let CHAINS: VOffset = 14
    static let CURRENCY: VOffset = 16
    static let ATTESTED: VOffset = 18
    static let TOTAL_VALUE: VOffset = 20
    static let ERRORS: VOffset = 22
    static let AS_OF_MS: VOffset = 24
    static let ATTESTER_ID: VOffset = 26
    static let SIGNATURE: VOffset = 28
    static let SIGNATURE_TYPE: VOffset = 30
  }

  ///  Identifier of this attestation; empty = not assigned.
  public var ATTESTATION_ID: String? { let o = _accessor.offset(VT.ATTESTATION_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var ATTESTATION_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.ATTESTATION_ID) }
  ///  Whose holdings these are: a peer identifier, an account or an
  ///  organization; empty = the attester's own.
  public var SUBJECT_ID: String? { let o = _accessor.offset(VT.SUBJECT_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var SUBJECT_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SUBJECT_ID) }
  ///  What the attestation is for, e.g. "security-bond", "treasury",
  ///  "collateral"; empty = general.
  public var PURPOSE: String? { let o = _accessor.offset(VT.PURPOSE); return o == 0 ? nil : _accessor.string(at: o) }
  public var PURPOSESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PURPOSE) }
  ///  Wallets read (in a request, the wallets to read).
  public var ACCOUNTS: FlatbufferVector<WHAAccount> { return _accessor.vector(at: VT.ACCOUNTS, byteSize: 4) }
  public var HOLDINGS: FlatbufferVector<WHAHolding> { return _accessor.vector(at: VT.HOLDINGS, byteSize: 4) }
  public var CHAINS: FlatbufferVector<WHAChain> { return _accessor.vector(at: VT.CHAINS, byteSize: 4) }
  ///  Valuation currency, ISO 4217 code, e.g. "USD".
  public var CURRENCY: String? { let o = _accessor.offset(VT.CURRENCY); return o == 0 ? nil : _accessor.string(at: o) }
  public var CURRENCYSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.CURRENCY) }
  ///  True when at least one chain was read, every chain is COMPLETE and
  ///  ERRORS is empty: TOTAL_VALUE is then the attested value.
  public var ATTESTED: Bool { let o = _accessor.offset(VT.ATTESTED); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Sum of all priced holdings' values in CURRENCY. Meaningful as the
  ///  attested value only when ATTESTED; otherwise a partial sum.
  public var TOTAL_VALUE: Double { let o = _accessor.offset(VT.TOTAL_VALUE); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Problems met, one per line, e.g. "ETH: lookup incomplete"; empty when
  ///  ATTESTED.
  public var ERRORS: FlatbufferVector<String?> { return _accessor.vector(at: VT.ERRORS, byteSize: 4) }
  ///  Unix milliseconds the holdings were read (the as-of time); 0 in a
  ///  request.
  public var AS_OF_MS: Int64 { let o = _accessor.offset(VT.AS_OF_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  ///  Identifier of the attester (a peer identifier or module identifier).
  public var ATTESTER_ID: String? { let o = _accessor.offset(VT.ATTESTER_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var ATTESTER_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.ATTESTER_ID) }
  ///  Attester's signature over the attestation, and its scheme (e.g.
  ///  "ed25519"); empty when unsigned.
  public var SIGNATURE: FlatbufferVector<UInt8> { return _accessor.vector(at: VT.SIGNATURE, byteSize: 1) }
  public func withUnsafePointerToSignature<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.SIGNATURE, body: body) }
  public var SIGNATURE_TYPE: String? { let o = _accessor.offset(VT.SIGNATURE_TYPE); return o == 0 ? nil : _accessor.string(at: o) }
  public var SIGNATURE_TYPESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SIGNATURE_TYPE) }
  public static func startWHA(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 14) }
  public static func add(ATTESTATION_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ATTESTATION_ID, at: VT.ATTESTATION_ID) }
  public static func add(SUBJECT_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SUBJECT_ID, at: VT.SUBJECT_ID) }
  public static func add(PURPOSE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PURPOSE, at: VT.PURPOSE) }
  public static func addVectorOf(ACCOUNTS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ACCOUNTS, at: VT.ACCOUNTS) }
  public static func addVectorOf(HOLDINGS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: HOLDINGS, at: VT.HOLDINGS) }
  public static func addVectorOf(CHAINS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CHAINS, at: VT.CHAINS) }
  public static func add(CURRENCY: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CURRENCY, at: VT.CURRENCY) }
  public static func add(ATTESTED: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ATTESTED, def: false,
   at: VT.ATTESTED) }
  public static func add(TOTAL_VALUE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TOTAL_VALUE, def: 0.0, at: VT.TOTAL_VALUE) }
  public static func addVectorOf(ERRORS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ERRORS, at: VT.ERRORS) }
  public static func add(AS_OF_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: AS_OF_MS, def: 0, at: VT.AS_OF_MS) }
  public static func add(ATTESTER_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ATTESTER_ID, at: VT.ATTESTER_ID) }
  public static func addVectorOf(SIGNATURE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SIGNATURE, at: VT.SIGNATURE) }
  public static func add(SIGNATURE_TYPE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SIGNATURE_TYPE, at: VT.SIGNATURE_TYPE) }
  public static func endWHA(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createWHA(
    _ fbb: inout FlatBufferBuilder,
    ATTESTATION_IDOffset ATTESTATION_ID: Offset = Offset(),
    SUBJECT_IDOffset SUBJECT_ID: Offset = Offset(),
    PURPOSEOffset PURPOSE: Offset = Offset(),
    ACCOUNTSVectorOffset ACCOUNTS: Offset = Offset(),
    HOLDINGSVectorOffset HOLDINGS: Offset = Offset(),
    CHAINSVectorOffset CHAINS: Offset = Offset(),
    CURRENCYOffset CURRENCY: Offset = Offset(),
    ATTESTED: Bool = false,
    TOTAL_VALUE: Double = 0.0,
    ERRORSVectorOffset ERRORS: Offset = Offset(),
    AS_OF_MS: Int64 = 0,
    ATTESTER_IDOffset ATTESTER_ID: Offset = Offset(),
    SIGNATUREVectorOffset SIGNATURE: Offset = Offset(),
    SIGNATURE_TYPEOffset SIGNATURE_TYPE: Offset = Offset()
  ) -> Offset {
    let __start = WHA.startWHA(&fbb)
    WHA.add(ATTESTATION_ID: ATTESTATION_ID, &fbb)
    WHA.add(SUBJECT_ID: SUBJECT_ID, &fbb)
    WHA.add(PURPOSE: PURPOSE, &fbb)
    WHA.addVectorOf(ACCOUNTS: ACCOUNTS, &fbb)
    WHA.addVectorOf(HOLDINGS: HOLDINGS, &fbb)
    WHA.addVectorOf(CHAINS: CHAINS, &fbb)
    WHA.add(CURRENCY: CURRENCY, &fbb)
    WHA.add(ATTESTED: ATTESTED, &fbb)
    WHA.add(TOTAL_VALUE: TOTAL_VALUE, &fbb)
    WHA.addVectorOf(ERRORS: ERRORS, &fbb)
    WHA.add(AS_OF_MS: AS_OF_MS, &fbb)
    WHA.add(ATTESTER_ID: ATTESTER_ID, &fbb)
    WHA.addVectorOf(SIGNATURE: SIGNATURE, &fbb)
    WHA.add(SIGNATURE_TYPE: SIGNATURE_TYPE, &fbb)
    return WHA.endWHA(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ATTESTATION_ID, fieldName: "ATTESTATION_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SUBJECT_ID, fieldName: "SUBJECT_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PURPOSE, fieldName: "PURPOSE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ACCOUNTS, fieldName: "ACCOUNTS", required: false, type: ForwardOffset<Vector<ForwardOffset<WHAAccount>, WHAAccount>>.self)
    try _v.visit(field: VT.HOLDINGS, fieldName: "HOLDINGS", required: false, type: ForwardOffset<Vector<ForwardOffset<WHAHolding>, WHAHolding>>.self)
    try _v.visit(field: VT.CHAINS, fieldName: "CHAINS", required: false, type: ForwardOffset<Vector<ForwardOffset<WHAChain>, WHAChain>>.self)
    try _v.visit(field: VT.CURRENCY, fieldName: "CURRENCY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ATTESTED, fieldName: "ATTESTED", required: false, type: Bool.self)
    try _v.visit(field: VT.TOTAL_VALUE, fieldName: "TOTAL_VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.ERRORS, fieldName: "ERRORS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.AS_OF_MS, fieldName: "AS_OF_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.ATTESTER_ID, fieldName: "ATTESTER_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SIGNATURE, fieldName: "SIGNATURE", required: false, type: ForwardOffset<Vector<UInt8, UInt8>>.self)
    try _v.visit(field: VT.SIGNATURE_TYPE, fieldName: "SIGNATURE_TYPE", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}
